import{_ as e,o as i,c as o,a3 as t}from"./chunks/framework.B8RmvCYz.js";const u=JSON.parse('{"title":"桌面端后端动态端口改造","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/optimization/dynamic-backend-port.md","filePath":"changelog/optimization/dynamic-backend-port.md","lastUpdated":1784962380000}'),l={name:"changelog/optimization/dynamic-backend-port.md"};function d(r,a,c,n,s,h){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="桌面端后端动态端口改造" tabindex="-1">桌面端后端动态端口改造 <a class="header-anchor" href="#桌面端后端动态端口改造" aria-label="Permalink to &quot;桌面端后端动态端口改造&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>桌面应用的后端曾固定监听 <code>8991</code>，当该端口被其他程序占用时后端无法启动。 旧的停止逻辑还会按端口查找并终止进程，存在误伤其他程序的风险。</p><h2 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h2><p>桌面应用启动时分配一个 <code>50000-65535</code> 范围内的回环端口：</p><ol><li>使用当前时间和进程 ID 生成随机起始位置。</li><li>从该位置循环探测 <code>127.0.0.1</code> 上的可用端口，已占用端口自动跳过。</li><li>Tauri 将选定端口通过 <code>--port</code> 传给 Python sidecar。</li><li>加载页通过 <code>get_backend_url</code> 获取本实例的真实地址，不依赖固定端口。</li><li>健康检查、状态检测和重启均读取本实例保存的端口。</li><li>重启复用原端口，保证当前 WebView 的 origin 不发生变化。</li><li>停止时只终止当前实例持有的子进程句柄，不再按端口扫描和杀进程。</li></ol><p>普通 MSI/Linux 模式和 MSIX 模式共用同一套端口分配器。</p><p>应用通过 Tauri 单实例插件保证同一时间只有一个桌面实例。再次启动应用不会创建新的 后端进程，而是显示、恢复并聚焦已经运行的主窗口。单实例插件在所有其他插件之前 注册，确保第二个进程在进入 <code>setup</code>、访问共享数据目录或拉起 sidecar 之前退出。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><ul><li>动态端口只用于桌面壳拉起的 Web 后端；直接运行 <code>start_back_end.py</code> 时仍可通过 <code>--port</code> 显式指定端口。</li><li>应用数据目录由唯一实例独占使用，不支持同时运行多个桌面实例。</li><li>仿真设备自身监听的 Modbus、IEC 104、IEC 61850 等业务端口不在本次改造范围内， 同一台机器上仍不能由不同实例重复占用同一个业务端口。</li></ul><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ul><li>单元测试确认动态端口位于 <code>50000-65535</code>。</li><li>单元测试确认端口被占用时会选择后续可用端口。</li><li>Rust 后端模块测试通过。</li></ul>',12)])])}const _=e(l,[["render",d]]);export{u as __pageData,_ as default};
